    List<Integer> parameters = getParameters(deviceSession.getDeviceId());

    for (int parameter : parameters) {
        switch (parameter) {
            case 0x01:
                position.set(Position.KEY_EVENT, buf.readUnsignedByte());
                break;
            case 0x02:
                position.setLatitude(buf.readIntLE() / 1000000.0);
                break;
