                    photos.remove(mediaId).release();
                }
            }

        }

        sendResponse(channel, true, type, buf.getShort(buf.writerIndex() - 6), null);

        return position;

    } else if (type == MSG_SERIAL) {

        position = new Position(getProtocolName());
