            cid = buf.readLong();
        } else if (type == MSG_GPS_LBS_6) {
            cid = buf.readUnsignedInt();
        } else {
            cid = buf.readUnsignedMedium();
        }

        // Skip any extra bytes present in the LBS block.
        int consumed = expected;
        if (length > consumed) {
