                position.set(Position.KEY_IGNITION, BitUtil.check(mask, 15));
                position.set(Position.PREFIX_IN + 2, BitUtil.check(mask, 14));
                if (BitUtil.check(mask, 12)) {
                    int value = BitUtil.to(mask, 9);
                    if (BitUtil.check(mask, 9)) {
                        value = -value;
                    }
                    position.set(Position.PREFIX_TEMP + 1, value);
                } else {
                    int value = BitUtil.to(mask, 10);
                    if (BitUtil.check(mask, 13)) {
