                    }
                    break;
                // For extended alarm type
                case 0xFE31:
                    if (buf.readableBytes() >= 2) {
                        buf.readUnsignedByte(); // alarm protocol
                        buf.readUnsignedByte(); // alarm type
                        int skip = length - 2;
                        if (skip > 0) {
                            buf.skipBytes(Math.min(skip, buf.readableBytes()));
                        }
                    } else {
                        buf.skipBytes(buf.readableBytes());
                    }
                    break;
                // For extended battery info
                case 0xFEA8:
                    if (buf.readableBytes() >= 3) {
                        buf.readUnsignedByte(); // battery status
                        position.set(Position.KEY_BATTERY_LEVEL, buf.readUnsignedByte());
                        buf.readUnsignedByte(); // battery alert
                    } else {
                        buf.skipBytes(buf.readableBytes());
                    }
                    break;
                default:
                    // Safely skip unknown TLV value fields without going past the buffer
                    buf.skipBytes(Math.min(length, buf.readableBytes()));
                    break;
            }
        }

        positions.add(position);
    }

