private Object decodeBasic(Channel channel, SocketAddress remoteAddress, ByteBuf buf) {

    // Save the starting index so we can later extract the packet serial number
    int beginIndex = buf.readerIndex();
    int length = buf.readUnsignedByte();
    // dataLength is used for payload‐processing; note that the packet body consists of
    // 1 byte protocol + (dataLength) bytes of data + 2 bytes serial + 2 bytes error-check = length bytes.
    int dataLength = length - 5;
    int type = buf.readUnsignedByte();
    // Calculate the serial number from the original packet.
    // The packet (excluding header/tail) starts at beginIndex and spans (length + 1) bytes (the length byte plus 'length' following bytes).
    // In many GT06 variants the last 4 bytes are reserved for serial (2 bytes) and error-check (2 bytes),
    // so the serial number is located at offset: beginIndex + (length - 1)
    int serial = buf.getShort(beginIndex + length - 1);

    Position position = new Position(getProtocolName());
    DeviceSession deviceSession = null;
    if (type != MSG_LOGIN) {
        deviceSession = getDeviceSession(channel, remoteAddress);
        if (deviceSession == null) {
            return null;
        }
        position.setDeviceId(deviceSession.getDeviceId());
        if (!deviceSession.contains(DeviceSession.KEY_TIMEZONE)) {
            deviceSession.set(DeviceSession.KEY_TIMEZONE, getTimeZone(deviceSession.getDeviceId()));
        }
    }

