    // In our setup the protocol sends either “normal” position messages or diagnostic (DTC) messages.
    // The DTC messages start with an uppercase 'C' while normal ones start with a lowercase 'c'.
    if ((char) buf.getByte(buf.readerIndex()) == 'C') {
        // --- This branch decodes a diagnostic (DTC) message ---
        int status = buf.readUnsignedShort();
        position.setValid(BitUtil.check(status, 15));
        position.set(Position.KEY_STATUS, status);
        position.set(Position.KEY_IGNITION, BitUtil.check(status, 14));

        int event = buf.readUnsignedShort();
        position.set(Position.KEY_ALARM, decodeAlarm(event));
        position.set(Position.KEY_EVENT, event);

        String time = buf.readCharSequence(12, StandardCharsets.US_ASCII).toString();
        DateBuilder dateBuilder = new DateBuilder()
                .setYear(Integer.parseInt(time.substring(0, 2)))
                .setMonth(Integer.parseInt(time.substring(2, 4)))
                .setDay(Integer.parseInt(time.substring(4, 6)))
                .setHour(Integer.parseInt(time.substring(6, 8)))
                .setMinute(Integer.parseInt(time.substring(8, 10)))
                .setSecond(Integer.parseInt(time.substring(10, 12)));
        position.setTime(dateBuilder.getDate());

        // The remaining bytes (each 2 bytes) represent a DTC code.
        // (DTC codes are encoded as 16‐bit values. The top 2 bits give the code type and the lower 14 bits the number.)
        StringBuilder dtcs = new StringBuilder();
        int dtcCount = buf.readableBytes() / 2;
        for (int i = 0; i < dtcCount; i++) {
            int raw = buf.readUnsignedShort();
            if (raw == 0) {
                continue;
            }
            int typeIndicator = (raw >> 14) & 0x03;
            String type;
            switch (typeIndicator) {
                case 0: type = "P"; break;
                case 1: type = "C"; break;
                case 2: type = "B"; break;
                case 3: type = "U"; break;
                default: type = "";
            }
            int codeNumber = raw & 0x3FFF;
            String codeStr = String.format("%s%04d", type, codeNumber);
            if (dtcs.length() > 0) {
                dtcs.append(" ");
            }
            dtcs.append(codeStr);
