        position.setDeviceId(deviceSession.getDeviceId());
        getLastLocation(position, null);
        int timeIndex = buf.indexOf(buf.readerIndex(), buf.writerIndex(), (byte) ',');
        buf.readerIndex(timeIndex + 12 + 2);
